// backend/src/repositories/refresh-token.repository.js
// SQL queries for the refresh_tokens table (with token families).

const db = require('../db/connection')

/**
 * Store a new refresh token hash.
 * @param {number} userId
 * @param {string} tokenHash - SHA-256 hex hash of the raw token
 * @param {Date} expiresAt
 * @param {string} [familyId] - The family UUID. If not provided, a new one is generated by the DB.
 * @returns {Promise<Object>}
 */
async function create(userId, tokenHash, expiresAt, familyId = null) {
  if (familyId) {
    const rows = await db.query(
      `INSERT INTO refresh_tokens (user_id, token_hash, expires, family_id)
       VALUES (@userId, @tokenHash, @expiresAt, @familyId)
       RETURNING *`,
      { userId, tokenHash, expiresAt, familyId }
    )
    return rows[0]
  } else {
    const rows = await db.query(
      `INSERT INTO refresh_tokens (user_id, token_hash, expires)
       VALUES (@userId, @tokenHash, @expiresAt)
       RETURNING *`,
      { userId, tokenHash, expiresAt }
    )
    return rows[0]
  }
}

/**
 * Find a token by its hash, returning its full status (even if revoked or replaced).
 * @param {string} tokenHash
 * @returns {Promise<Object|null>}
 */
async function getByHash(tokenHash) {
  const rows = await db.query(
    `SELECT *
     FROM refresh_tokens
     WHERE token_hash = @tokenHash`,
    { tokenHash }
  )
  return rows[0] || null
}

/**
 * Revoke a specific refresh token by its DB id.
 * @param {number} id
 */
async function revoke(id) {
  await db.query(
    `UPDATE refresh_tokens SET revoked = NOW() WHERE id = @id`,
    { id }
  )
}

/**
 * Revoke an entire family of tokens (used when token reuse is detected).
 * @param {string} familyId
 */
async function revokeFamily(familyId) {
  await db.query(
    `UPDATE refresh_tokens SET revoked = NOW() WHERE family_id = @familyId`,
    { familyId }
  )
}

/**
 * Mark a token as replaced, starting its grace period.
 * @param {number} id - Token ID to mark as replaced
 * @param {string} replacedByHash - The hash of the new token replacing it
 * @param {number} graceMs - Milliseconds of grace period
 */
async function markReplaced(id, replacedByHash, graceMs = 30000) {
  await db.query(
    `UPDATE refresh_tokens
     SET replaced_by_token_hash = @replacedByHash,
         replacement_grace_expires = NOW() + (@graceMs || ' milliseconds')::interval
     WHERE id = @id`,
    { id, replacedByHash, graceMs: `${graceMs}` }
  )
}

module.exports = { create, getByHash, revoke, revokeFamily, markReplaced }
